\cite{4}\label{lem1.1}
	Let $K\in \mathbb{N}$, and $\mathbb{S}$ be a $K\mathbb{Z}$-periodic set in $\mathbb{Z}$. Write $\mathbb{S}_K=\mathbb{S}\cap \mathbb{N}_K$. Then the restriction of $z_K$ to $\ell^2(\mathbb{S})$ is a unitary linear operator from $\ell^2(\mathbb{S})$ to the Hilbert space  $\ell^2(Q)$ where $Q=\mathbb{S}_K\times [0,1[$ and 
	$$\ell^2(Q):=\{\psi:Q \rightarrow \mathbb{C}:\, \displaystyle{\sum_{j\in \mathbb{S}_K}\int_{0}^1 \vert \psi(j,\theta)\vert^2 \, d\theta}< \infty\}.$$

\cite{4}
	Let $N,M\in \mathbb{N}$ and $p,q\in \mathbb{N}$ such that $p\wedge q=1$ and $\displaystyle{\frac{N}{M}=\frac{p}{q}}.$ Then 
	the set \\$\Delta:=\{j+kM-rN:\; j\in \mathbb{N}_{\frac{M}{q}},\, k\in \mathbb{N}_p,\, r\in \mathbb{N}_q\}$ is $qN$-congruent to $\mathbb{N}_{pM}$.

\cite{3} \label{KRK}\hspace{0.3cm}
	Let $g:=\{g_l\}_{l\in \mathbb{N}_L}\subset \ell^2(\mathbb{S})$.
	\begin{enumerate}
		\item  $\mathcal{G}(g,L,M,N)$ is a frame for $\ell^2(\mathbb{S})$ only when $\displaystyle{\frac{card(\mathbb{S}_N)}{M}}\leq L$.
		\item  Assume that $\mathcal{G}(g,L,M,N)$ is a frame for $\ell^2(\mathbb{S})$. Then following statements are equivalent: 
		\begin{enumerate}
			\item $\mathcal{G}(g,L,M,N)$ is a  Riesz basis  (exact frame) for $\ell^2(\mathbb{S})$.
			\item $\displaystyle{\frac{card(\mathbb{S}_N)}{M}}=L$.
		\end{enumerate}
	\end{enumerate}

\cite{4}\label{lem2.6}
	Let $M \in \mathbb{N}$ and $E \subset \mathbb{Z}$. Then the following conditions are equivalent:
	\begin{enumerate}
		\item $\left\{ e^{2\pi im/M} \cdot \chi_E(\cdot) : m \in \mathbb{N}_M \right\}$ is a tight frame for $\ell^2(E)$ with frame bound $M$.
		\item $\left\{ e^{2\pi im/M} \cdot \chi_E(\cdot) : m \in \mathbb{N}_M \right\}$ is complete in $\ell^2(E)$.
		\item $E$ is $M\mathbb{Z}$-congruent to a subset of $\mathbb{N}_M$.
		\item $\displaystyle{\sum_{k \in \mathbb{Z}} \chi_E(\cdot + kM) \leq 1}$ on $\mathbb{Z}$.
	\end{enumerate}

\cite{1}\label{PRO}
	Let $\{f_i\}_{i\in \mathcal{I}}$, where $\mathcal{I}$ is a countable sequence,  be a Parseval frame for a separable Hilbert space $H$. Then the following statements are equivalent:
	\begin{enumerate}
		\item $\{f_i\}_{i\in \mathcal{I}}$ is a Riesz basis.
		\item $\{f_i\}_{i\in \mathcal{I}}$ is an orthonormal basis.
		\item For all $i\in \mathcal{I}$, $\|f_i\|=1.$
	\end{enumerate}

\label{lem2.9}
	For all $j\in \mathbb{Z}$, $\mathcal{K}(j)$ is an orthogonal projection on $\mathbb{C}^p$. i.e.
	\begin{enumerate}
		\item $\mathcal{K}(j)^2=\mathcal{K}(j)$.
		\item  $\mathcal{K}(j)^*=\mathcal{K}(j)$.
	\end{enumerate}

\label{prop2.1}
	Let $g:=\{g_l\}_{l\in \mathbb{N}_L}\subset \ell^2(\mathbb{S})$. Let $M,N\in \mathbb{N}$ and $p,q\in \mathbb{N}$ such that $p\wedge q=1$. Then the integer-valued function $(j,\theta)\rightarrow rank(Z_g(j,\theta))$ is $\displaystyle{\frac{M}{q}}$-periodic with respect to $j$ and $1$-periodic with respect to $\theta$. Moreover,  for all $j\in \mathbb{Z}$ and a.e $ \theta \in \mathbb{R}$, we have: 
	\begin{equation}
		rank(Z_g(j,\theta))\leq \; card(\mathcal{K}_j).
	\end{equation}

\label{lem2.2}
	For all $j\in \mathbb{Z}$,  a.e $\theta \in \mathbb{R}$, $k'\in \mathbb{N}_p$ and $r'\in \mathbb{N}_q$, we have: 
	$$rank(Z_g(j,\theta))=rank(Z_g(j+k'M+r'N,\theta)).$$

\label{lem2.4}
	Let $g:=\{g_l\}_{l\in \mathbb{N}_L}\subset \ell^2(\mathbb{Z})$. Let $f\in \ell^2(\mathbb{Z})$. Then the following statements are equivalent:
	\begin{enumerate}
		\item $f$ is orthogonal to $\mathcal{G}(g,L,M,N)$.
		\item For all $j\in \mathbb{N}_M$, a.e. $\theta\in [0,1[$, $Z_g(j,\theta)F(j,\theta)=0$.
	\end{enumerate}
	Where $F(j,\theta):=(\overline{z_{pM}f(j+kM,\theta)})_{k\in \mathbb{N}_p}^t$ for $j\in \mathbb{N}_M
	$ and a.e $\theta\in [0,1[$.

\label{prop3.5}
	Let $g:=\{g_l\}_{l\in \mathbb{N}_L}\subset \ell^2(\mathbb{S})$. Then the following statements are equivalent:
	\begin{enumerate}
		\item $\mathcal{G}(g,L,M,N)$ is complete in $\ell^2(\mathbb{S})$.
		\item For all $j\in \mathbb{N}_{\frac{M}{q}}$, a.e $\theta \in [0,1[$, $rank(Z_g(j,\theta))=card(\mathcal{K}_j)$.
		\item For all $j\in \mathbb{Z}$, a.e $\theta\in \mathbb{R}$, $rank(Z_g(j,\theta))=card(\mathcal{K}_j)$.
	\end{enumerate}

\label{prop3.6}
	Given \(g:=\{g_l\}_{l\in \mathbb{N}_L} \subset \ell^2(\mathbb{S})\). Then the following statements are equivalent:
	\begin{enumerate}
		\item $\mathcal{G}(g,L, M,N)\) is a frame for \(\ell^2(S)$ with frame bounds $0 < A \leq B $.
		\item 
		\begin{equation}
			\frac{A}{M}.\mathcal{K}(j)
			\leq \sum_{l\in \mathbb{N}_L} Z_{g_l}^*(j, \theta)Z_{g_l}(j, \theta) \leq \frac{B}{M}.\mathcal{K}(j).
		\end{equation}
		for all $j \in \frac{M}{q}\) and a.e $\theta \in [0, 1[$.
		\item The inequality $(3)$ holds for all $j \in \mathbb{N}_M$ and a.e $\theta \in [0, 1[$.\\
	\end{enumerate}

\label{lem3.7}
	Denote $L^{\infty}(\mathbb{S}_{pM}\times [0,1[)$ the set of functions $F$ on $\mathbb{S}_{pM}\times [0,1[$ such that for all $j\in \mathbb{S}_{pM}$, $F(j,.)\in L^{\infty}([0,1[)$, and  $\Delta := z_{pM \mid \ell^2(\mathbb{S})}^{-1}\left(L^{\infty}(\mathbb{S}_{pM} \times [0,1[)\right).$ Let $g:=\{g_l\}_{l\in \mathbb{N}_L}\subset \ell^2(\mathbb{S})$. Then the following statements are equivalent:
	\begin{enumerate}
		\item $\mathcal{G}(g,L,M,N)$ is a frame for $\ell^2(\mathbb{S})$ with frame bounds $A\leq B$.
		\item For all  $f \in \Delta$, we have:
		$$
		\begin{array}{rcl}
		\displaystyle{\frac{A}{M} \sum_{j=0}^{M-1} \int_{0}^{1} \|F(j, \theta)\|^2  d\theta} &\leq& \displaystyle{\sum_{l=0}^{l-1}\sum_{j=0}^{M-1} \int_{0}^{1} \| Z_{g_l}(j, \theta) F(j, \theta)\|^2  d\theta}\\
		& \leq& \displaystyle{\frac{B}{M} \sum_{j=0}^{M-1} \int_{0}^{1} \|F(j, \theta)\|^2 d\theta.}
		\end{array}$$
		Where $F(j,\theta)$, for all $j\in \mathbb{N}_M$ and a.e $\theta \in [0,1[$, is as defined in lemma \ref{lem2.4}.
	\end{enumerate}

\hspace{1cm}
	\begin{enumerate}
		\item[]$(1)\Longrightarrow (3)$: Assume that $\mathcal{G}(g,L,M,N)$ is a frame for $\ell^2(\mathbb{S})$. Then for all $f\in \Delta$, \begin{equation*}
\begin{array}{rcl}
\displaystyle{\frac{A}{M} \sum_{j=0}^{M-1} \int_{0}^{1} \|F(j, \theta)\|^2 \, d\theta} &\leq& \displaystyle{\sum_{l=0}^{l-1}\sum_{j=0}^{M-1} \int_{0}^{1} \| Z_{g_l}(j, \theta) F(j, \theta)\|^2 \, d\theta } \\
&\leq& \displaystyle{\frac{B}{M} \sum_{j=0}^{M-1} \int_{0}^{1} \|F(j, \theta)\|^2 \, d\theta.}
		\end{array}	
		\end{equation*}
		Fix $x:=\{x_k\}_{k\in \mathbb{N}_p}\in  \mathbb{C}^p$, $j_0\in \mathbb{N}_M$ and $h\in L^{\infty}([0,1[)$, and define for all $j\in \mathbb{N}_M$ and a.e $\theta\in [0,1[$, $F(j,\theta):=\{\delta_{j,j_0}\,\chi_{\mathcal{K}_j}(k)\,x_k\, h(\theta) \}_{k\in \mathbb{N}_p}$. \\Then: $\displaystyle{ \sum_{j=0}^{M-1} \int_{0}^{1} \|F(j, \theta)\|^2 \, d\theta=\|\mathcal{K}(j_0)x\|^2\int_0^1 \vert h(\theta)\vert^2 \,d\theta=}$\\ $\displaystyle{\langle \mathcal{K}(j_0)x,x\rangle \int_0^1 \vert h(\theta)\vert^2\,d\theta}$ (lemma \ref{lem2.9}). On the other hand, we have: $$
		\begin{array}{rcl}
			\displaystyle{\sum_{l=0}^{l-1}\sum_{j=0}^{M-1} \int_{0}^{1} \| Z_{g_l}(j, \theta) F(j, \theta)\|^2 \, d\theta }&=&\displaystyle{\sum_{l=0}^{l-1} \int_{0}^{1} \| Z_{g_l}(j_0, \theta) F(j_0, \theta)\|^2 \, d\theta} \\
			&=&\displaystyle{\sum_{l=0}^{l-1} \int_{0}^{1} \sum_{r=0}^{q-1} \left\vert \left(Z_{g_l}(j_0, \theta) F(j_0, \theta)\right)_r \,\right\vert^2 \, d\theta} \\
			&=&\displaystyle{\sum_{l=0}^{l-1} \int_{0}^{1} \sum_{r=0}^{q-1} \left\vert \sum_{k=0}^{p-1} Z_{g_l}(j_0, \theta)_{r,k} F(j_0, \theta)_k \,\right\vert^2 \, d\theta} \\
			&=&\displaystyle{\sum_{l=0}^{l-1} \int_{0}^{1} \sum_{r=0}^{q-1} \left\vert \sum_{k=0}^{p-1} Z_{g_l}(j_0, \theta)_{r,k} \,\chi_{\mathcal{K}_{j_0}}(k)\,x_k\, h(\theta)\,\right\vert^2 d\theta }\\
			&=&\displaystyle{\sum_{l=0}^{l-1} \int_{0}^{1} \sum_{r=0}^{q-1}\left \vert \sum_{k=0}^{p-1} Z_{g_l}(j_0, \theta)_{r,k} (\mathcal{K}(j_0)x)_k \right\vert^2 \vert h(\theta)\vert^2 d\theta} \\
			&=&\displaystyle{\sum_{l=0}^{l-1} \int_{0}^{1} \sum_{r=0}^{q-1} \left\vert \left(Z_{g_l}(j_0, \theta)\mathcal{K}(j_0)x\right)_r \right\vert^2 \vert h(\theta)\vert^2 d\theta}\\
			&=&\displaystyle{\sum_{l=0}^{l-1} \int_{0}^{1} \left\|Z_{g_l}(j_0,\theta)\mathcal{K}(j_0)x \right\|^2 \vert h(\theta)\vert^2 d\theta} \\
			&=&\displaystyle{\sum_{l=0}^{l-1} \int_{0}^{1} \left\|Z_{g_l}(j_0,\theta)x \,\right\|^2 \vert h(\theta)\vert^2  d\theta}\;\;\; \text{ by lemma }\ref{lem2.8} \\
			&=&\displaystyle{\int_{0}^{1} \left\langle \sum_{l=0}^{l-1} Z_{g_l}(j_0,\theta)^*Z_{g_l}(j_0,\theta)x,x\right\rangle \vert h(\theta)\vert^2 d\theta}. \\
		\end{array}$$
		Then for all $j\in \mathbb{N}_M$,  $x\in \mathbb{C}^p$ and $h\in L^{\infty}([0,1[)$, we have: 
		\begin{equation}
		\begin{array}{rcl}
\displaystyle{\frac{A}{M}.\langle \mathcal{K}(j)x,x\rangle \,\int_0^1\vert h(\theta)\vert^2 \,d\theta} &\leq& \displaystyle{\int_{0}^{1} \left\langle \sum_{l=0}^{l-1} Z_{g_l}(j,\theta)^*Z_{g_l}(j,\theta)x,x\right\rangle \,\vert h(\theta)\vert^2 \, d\theta} \\
&\leq& \displaystyle{\frac{B}{M}.\langle \mathcal{K}(j)x,x\rangle \int_0^1\vert h(\theta)\vert^2\, d\theta.}
	\end{array}
		\end{equation}
		For $j\in \mathbb{N}_M$ and $x\in \mathbb{C}^p$ fixed, denote $C=\displaystyle{\frac{A}{M}.\langle \mathcal{K}(j)x,x\rangle}$ and $D=\displaystyle{\frac{B}{M}.\langle \mathcal{K}(j)x,x\rangle}$. Assume, by contradiction, that \begin{equation} C>\displaystyle{\left\langle \sum_{l=0}^{L-1}Z_{g_l}(j,\theta)^*Z_{g_l}(j,\theta)x,x\right\rangle} ,
		\end{equation} on a subset of $[0,1[$ with a positive measure. Denote 
		$D=\{\theta \in [0,1[:\; (8) \text{ holds}\}.$\\
		For all $k\in \mathbb{N}$, denote: $$D_k:=\left\{\theta\in [0,1[:\; C-\displaystyle{\frac{C}{k+1}}\leq \displaystyle{\langle \sum_{l=0}^{L-1}Z_{g_l}(j,\theta)^*Z_{g_l}(j,\theta)x,x\rangle} \leq C-\displaystyle{\frac{C}{k}}\right\}.$$
		It is clear that $\{D_k\}_{k\in \mathbb{N}}$ forms a partition for $D$. Since $mes(D)>0$, then there exists $k\in \mathbb{N}$ such that $mes(D_k)>0$. Let $h:=\chi_{D_k}$, we have: $$\begin{array}{rcl}
			\displaystyle{\int_{0}^{1} \left\langle \sum_{l=0}^{l-1} Z_{g_l}(j,\theta)^*Z_{g_l}(j,\theta)x,x\right\rangle \,\vert h(\theta)\vert^2 \, d\theta}&=&\displaystyle{\int_{D_k} \left\langle \sum_{l=0}^{l-1} Z_{g_l}(j,\theta)^*Z_{g_l}(j,\theta)x,x\right\rangle d\theta}\\
			&\leq&(C-\displaystyle{\frac{C}{k}}). mes(D_k)\\
			&<&C.mes(D_k)\\
			&=&C\displaystyle{\int_0^1 \vert h(\theta)\vert^2\,d\theta}.
		\end{array}$$
	 Contradiction with $(7)$. 
		Suppose, again by contradiction, that \begin{equation} D<\displaystyle{\left\langle \sum_{l=0}^{L-1}Z_{g_l}(j,\theta)^*Z_{g_l}(j,\theta)x,x\right\rangle}, 
		\end{equation} on a subset of $[0,1[$ with a positive measure. Denote 
		$D'=\{\theta \in [0,1[:\; (9) \text{ holds}\}.$\\
		For all $k\in \mathbb{N}$, $m\in \mathbb{N}$, denote $$D_{k,m}':=\left\{\theta\in [0,1[:\; D(k+\displaystyle{\frac{1}{m+1}})\leq \displaystyle{\langle \sum_{l=0}^{L-1}Z_{g_l}(j,\theta)^*Z_{g_l}(j,\theta)x,x\rangle} \leq D(k+\displaystyle{\frac{1}{m}})\right\}.$$
		It is clear that $\{D_{k,m}'\}_{k\in \mathbb{N}}$ forms a partition for $D'$. Since $mes(D')>0$, then there exist $k\in \mathbb{N}$ and $m\in \mathbb{N}$ such that $mes(D_{k,m}')>0$. Let $h:=\chi_{D_{k,m}'}$, we have: $$\begin{array}{rcl}
			\displaystyle{\int_{0}^{1} \langle \sum_{l=0}^{l-1} Z_{g_l}(j,\theta)^*Z_{g_l}(j,\theta)x,x\rangle \,\vert h(\theta)\vert^2 \, d\theta}&=&\displaystyle{\int_{D_{k,m}'} \langle \sum_{l=0}^{l-1} Z_{g_l}(j,\theta)^*Z_{g_l}(j,\theta)x,x\rangle \, d\theta}\\
			&\geqslant&D(k+\displaystyle{\frac{1}{m+1}}). mes(D_{k,m}')\\
			&>&D.mes(D_{k,m}')\\
			&=&D\displaystyle{\int_0^1 \vert h(\theta)\vert^2\,d\theta}.
		\end{array}$$
		Contradiction with $(7)$. Hence for all $j\in \mathbb{N}_M$, and a.e $\theta \in [0,1[$, we have: 
		\begin{equation*}
			\frac{A}{M}.\mathcal{K}(j)
			\leq \sum_{l\in \mathbb{N}_L} Z_{g_l}^*(j, \theta)Z_{g_l}(j, \theta) \leq \frac{B}{M}.\mathcal{K}(j).
		\end{equation*}
		\item[]$(3)\Longrightarrow(1)$: Assume $(3)$. For $f\in \Delta$, $j\in \mathbb{N}_M$ and a.e $\theta\in [0,1[$,  the $k$-th component of $F(j,\theta)$ is zero if $k\notin \mathcal{K}_j$. Then $\mathcal{K}(j)F(j,\theta)=F(j,\theta)$. Then: \begin{equation*}
			\frac{A}{M}\|F(j,\theta)\|^2\leq \left \langle \sum_{l=0}^{L-1} Z_{g_l}(j,\theta)^*Z_{g_l}(j,\theta)F(j,\theta),F(j,\theta)\right \rangle\leq \frac{B}{M}\|F(j,\theta)\|^2.
		\end{equation*}
		Hence: \begin{equation*}
			\frac{A}{M}\sum_{j=0}^{M-1}\int_0^1\|F(j,\theta)\|^2\leq \sum_{l=0}^{L-1}\sum_{j=0}^{M-1}\int_0^1 \| Z_{g_l}(j,\theta)F(j,\theta)\|^2\leq \frac{B}{M}\sum_{j=0}^{M-1}\int_0^1\|F(j,\theta)\|^2.
		\end{equation*}
		Then lemma \ref{lem3.7} implies $(1)$.
		\item[]$(3)\Longrightarrow (2)$: Since $\mathbb{N}_{\frac{M}{q}}\subset \mathbb{N}_M$.
		\item[]$(2)\Longrightarrow (3)$: Assume $(2)$. Then the inequality $(3)$ holds for all $ j \in \mathbb{N}_{\frac{M}{q}}$ and a.e. $ \theta \in [0, 1[$. Let's prove that it  holds for all $ j \in \mathbb{N}_M$ and a.e. $\theta \in [0, 1[$. Let $j \in \mathbb{N}_M$. By Lemma \ref{lem2.5}, there exists a unique $(j', r', k', \ell') \in \mathbb{N}_{\frac{M}{q}} \times \mathbb{N}_q \times \mathbb{N}_p \times \mathbb{Z}$ such that $j = j' + k'M - r'N + \ell'qN$. Then, by the
		quasiperiodicity of the discrete Zak transform, we have, for all $l\in \mathbb{N}_L$, after a simple calculation:

		$(Z_{g_l}(j, \theta)^*Z_{g_l}(j, \theta))_{k_1, k_2} =$\\
		$\displaystyle{\sum_{r=0}^{q-1}
		(\overline{Z_{qN} g_l) (j' + (k_1 + k')M - (r + r')N, \theta)} (Z_{qN}g) (j' + (k_2 + k')M - (r + r')N, \theta)}$
		\begin{equation*}
			=
			\begin{cases} 
				(Z_{g_l}(j', \theta)^*Z_{g_l}(j', \theta))_{k_1+k', k_2+k'}, & \text{if } k_1 + k' < p, \; k_2 + k' < p \\
				e^{-2\pi i\theta} (Z_{g_l}(j', \theta)^*Z_{g_l}(j', \theta))_{k_1+k', k_2+k'-p}, & \text{if } k_1 + k' < p, \; k_2 + k' \geq p \\
				e^{2\pi i\theta} (Z_{g_l}(j', \theta)^*Z_{g_l}(j', \theta))_{k_1+k'-p, k_2+k'}, & \text{if } k_1 + k' \geq p, \; k_2 + k' < p \\
				(Z_{g_l}(j', \theta)^*Z_{g_l}(j', \theta))_{k_1+k'-p, k_2+k'-p}, & \text{if } k_1 + k' \geq p, \; k_2 + k' \geq p.
			\end{cases}
		\end{equation*}
		for $k_1, k_2 \in \mathbb{N}_p$ and a.e. $\theta \in [0, 1[$.\\
		Define \( V: \mathbb{C}^p \to \mathbb{C}^p \) by $Vx = y = (y_0, y_1, \ldots, y_{p-1})^t$, where:

		$$
		y_k =
		\begin{cases} 
			e^{-2\pi i \theta}x_{k-k'+p}, & \text{if } 0 \leq k < k' \\
			x_{k-k'}, & \text{if } k' \leq k < p,
		\end{cases}
		$$
		for $x \in \mathbb{C}^p$. Then $V$ is a unitary operator, and

		$$
		\langle Z_{g_l}(j, \theta)^*Z_{g_l}(j, \theta)x, x \rangle = \langle Z_{g_l}(j', \theta)^*Z_{g_l}(j', \theta)Vx, Vx \rangle,
		$$
		for a.e. $\theta \in [0, 1[$ and all $x \in \mathbb{C}^p$. Then, by $(2)$, we have:

		\begin{equation}
			\frac{A}{M} \langle V^*\mathcal{K}(j') Vx, x \rangle
			\leq \left\langle \sum_{l=0}^{L-1}Z_{g_l}(j, \theta)^*Z_{g_l}(j, \theta)x, x \right\rangle
			\leq \frac{B}{M}\langle V^*\mathcal{K}(j') Vx, x \rangle,
		\end{equation}
		for a.e. \( \theta \in [0, 1) \) and each $x \in \mathbb{C}^p$. When $k+k' < p$, $k+k' \in \mathcal{K}_{j'}$ if and only if $j'+(k+k')M \in\mathbb{S}$,  equivalently, $j' + k'M - r'N + \ell'qN + kM \in\mathbb{S}$, i.e. $j + kM \in \mathbb{S}$. Therefore, $k + k' \in \mathcal{K}_j$ if and only if $k \in \mathcal{K}_j$ when $k + k' < p$. Similarly, $k + k' - p \in \mathcal{K}_{j'}$ if and only if $k \in \mathcal{K}_j$ when
		$k + k' \geq p$. It follows that:
		$$
		V^*\mathcal{K}(j')V = \mathcal{K}(j).
		$$
		Which together with $(10)$ gives $(3)$. The proof is completed.
	\end{enumerate}

In the case of $\mathbb{S}=\mathbb{Z}$. For all $j\in \mathbb{N}_{\frac{M}{q}}$, $\mathcal{K}_j=\mathbb{N}_p$. Then the condition $(2)$ in the Theorem \ref{prop3.5} is equivalent to $rank(Z_g(j,\theta)\,)=p$ for all $j\in \mathbb{N}_{\frac{M}{q}}$ and a.e $\theta \in [0,1[$. And the condition $(2)$ in the Theorem $\ref{prop3.6}$ is equivalent to: For all $j\in \mathbb{N}_{\frac{M}{q}}$ and a.e $\theta \in [0,1[$, 
	\begin{equation*}
		\frac{A}{M}.I_{p,p}
		\leq \sum_{l\in \mathbb{N}_L} Z_{g_l}^*(j, \theta)Z_{g_l}(j, \theta) \leq \frac{B}{M}.I_{p,p}.
	\end{equation*}

	Where $I_{p,p}$ is the identity matrix in $\mathcal{M}_{p,p}$.

\label{lem4.1}\hspace{1cm}
	\begin{enumerate}
		\item $card(\mathcal{K}_j)\leq \,qL$ for all $j\in \mathbb{N}_{\frac{M}{q}}$ $\Longrightarrow$ $card(\mathbb{S}_N)\leq\, LM$.
		\item Assume that $card(\mathcal{K}_j)\leq \,qL$ for all $j\in \mathbb{N}_{\frac{M}{q}}$. Then:
		$$card(\mathcal{K}_j)=qL \text{ for all }j\in \mathbb{N}_{\frac{M}{q}}\;\Longleftrightarrow \;card(\mathbb{S}_N)=\, LM.$$
	\end{enumerate}

\label{lem4.2}
	Let $L,M\in \mathbb{N}$ and $E_0,\,E_1,\, \ldots,\,E_{L-1}\subset \mathbb{Z}$ be mutually disjoint. Denote $E=\displaystyle{\bigcup_{l\in \mathbb{N}_L}E_l}$. Then the following statements are equivalent:
	\begin{enumerate}
		\item $\{e^{2\pi i \frac{m}{M}.}\chi_{E_l}\}_{m\in \mathbb{N}_M, \, l\in \mathbb{N}_L}$ is complete in  $\ell^2(E)$.
		\item For all $l\in \mathbb{N}_L$, $\{e^{2\pi i \frac{m}{M}.}\chi_{E_l}\}_{m\in \mathbb{N}_M}$ is complete in $\ell^2(E_l)$.
	\end{enumerate}

\hspace{1cm}
	\begin{enumerate}
		\item[]$(1)\Longrightarrow (2)$: Assume $(1)$. Fix $l_0\in \mathbb{N}_L$ and let $f\in \ell^2(E_{l_0})$ be orthogonal to  $\{e^{2\pi i \frac{m}{M}.}\chi_{E_{l_0}}\}_{m\in \mathbb{N}_M}$. 
		Define $\overline{f}\in \ell^2(E)$ by $\overline{f}(j)=f(j)$ if $j\in E_{l_0}$ and $0$ otherwise. It is clear that if $l\neq l_0$, $\overline{f}$ is orthogonal to  $\{e^{2\pi i \frac{m}{M}.}\chi_{E_l}\}_{m\in \mathbb{N}_M}$. And we have: 
		$$\begin{array}{rcl}
			\langle \overline{f},e^{2\pi i \frac{m}{M}.}\chi_{E_{l_0}}\rangle&=&\displaystyle{\sum_{j\in E}\overline{f}(j)e^{-2\pi i \frac{m}{M}j}\chi_{E_{l_0}}(j)}\\
			&=& \displaystyle{\sum_{j\in E_{l_0}}f(j)e^{-2\pi i \frac{m}{M}j}\chi_{E_{l_0}}(j)}\\
			&=&0\;\;\; \text{ since } f\text{ is orthogonal to } \{e^{2\pi i \frac{m}{M}.}\chi_{E_{l_0}}\}_{m\in \mathbb{N}_M}.
		\end{array}$$
		Then $\overline{f}$ is orthogonal to $\{e^{2\pi i \frac{m}{M}.}\chi_{E_l}\}_{m\in \mathbb{N}_M, l\in \mathbb{N}_L}$ which is complete in $\ell^2(E)$, thus $\overline{f}=0$ on $E$, and then $f=0$ on $E_l$.

		\item[]$(2)\Longrightarrow(1)$: Assume $(3)$ and let $h\in \ell^2(E)$ be orthogonal to $\{e^{2\pi i \frac{m}{M}.}\chi_{E_l}\}_{m\in \mathbb{N}_M, l\in \mathbb{N}_L}$. For all $l\in \mathbb{N}_L$, define $h_l\in \ell^2(E_l)$ as the restriction of $h$ on $E_l$, i.e.  $h_l:=h|_{E_l}$. Let $l\in \mathbb{N}_L$. Fix $l\in \mathbb{N}_L$. Since $h$ is orthogonal to $\{e^{2\pi i \frac{m}{M}.}\chi_{E_l}\}_{m\in \mathbb{N}_M}$, then $\displaystyle{\sum_{j\in E}h(j) e^{-2\pi i \frac{m}{M}.}\chi_{E_l}(j)=0}$, then $\displaystyle{\sum_{j\in E_l}h(j) e^{-2\pi i \frac{m}{M}.}\chi_{E_l}(j)=0}$, thus $\displaystyle{\sum_{j\in E_l}h_l(j) e^{-2\pi i \frac{m}{M}.}\chi_{E_l}(j)=\langle h_l,e^{2\pi i \frac{m}{M}.}\chi_{E_l}\rangle =0}$. Hence $h_l$ is orthogonal to  $\{e^{2\pi i \frac{m}{M}.}\chi_{E_l}\}_{m\in \mathbb{N}_M}$ which is complete in $\ell^2(E_l)$. Hence $h_l=0$ on $E_l$. This for all $l\in \mathbb{N}_L$, therfore $h=0$ on $E$. Hence $\{e^{2\pi i \frac{m}{M}.}\chi_{E_l}\}_{m\in \mathbb{N}_M,l\in \mathbb{N}_L}$ is complete in $\ell^2(E)$.

	\end{enumerate}

\label{lem4.3}
	Let $L,M\in \mathbb{N}$ and $E_0,\,E_1,\, \ldots,\,E_{L-1}\subset \mathbb{Z}$  be mutually disjoint. Denote $E=\displaystyle{\bigcup_{l\in \mathbb{N}_L}E_l}$. Then the following statements are equivalent:
	\begin{enumerate}
		\item $\{e^{2\pi i \frac{m}{M}.}\chi_{E_l}\}_{m\in \mathbb{N}_M, \, l\in \mathbb{N}_L}$ is a tight frame for $\ell^2(E)$ with frame bound $M$.
		\item For all $l\in \mathbb{N}_L$, $\{e^{2\pi i \frac{m}{M}.}\chi_{E_l}\}_{m\in \mathbb{N}_M}$ is a tight frame for $\ell^2(E_l)$ with frame bound $M$.
	\end{enumerate}

\hspace{1cm}
	\begin{enumerate}
		\item[]$(1)\Longrightarrow (2)$: Assume $(1)$. Fix $l_0\in \mathbb{N}_L$ and let $f\in \ell^2(E_{l_0})$. Define $\overline{f}\in \ell^2(E)$ by $\overline{f}(j)=f(j)$ if $j\in E_{l_0}$ and $0$ otherwise. It is clear that $\langle \overline{f},e^{2\pi i \frac{m}{M}.}\chi_{E_l}\rangle=0$ if $l\neq l_0$ and that $\|\overline{f}\|=\|f\|$. Together with the fact that $\{e^{2\pi i \frac{m}{M}.}\chi_{E_l}\}_{m\in \mathbb{N}_M, \, l\in \mathbb{N}_L}$ is a tight frame for $\ell^2(E)$ with frame bound $M$, we have: $$
		\begin{array}{rcl}
			M\|f\|^2&=&\displaystyle{\sum_{m=0}^{M-1}\left\vert \sum_{j\in E}\overline{f}(j)e^{-2\pi i \frac{m}{M}j}\chi_{E_{l_0}}(j)\right\vert^2}\\
			&=&\displaystyle{\sum_{m=0}^{M-1}\left\vert\sum_{j\in E_{l_0}}f(j)e^{-2\pi i \frac{m}{M}j}\chi_{E_{l_0}}(j)\right\vert^2}\\
			&=&\displaystyle{\sum_{m=0}^{M-1}\left\vert\langle f,e^{2\pi i \frac{m}{M}.}\chi_{E_{l_0}}\rangle\right\vert^2}.
		\end{array}$$
		Hence $\{e^{2\pi i \frac{m}{M}.}\chi_{E_{l_0}}\}_{m\in \mathbb{N}_M}$ is a tight frame for $\ell^2(E_{l_0})$ with frame bound $M$. And this for all $l_0\in \mathbb{N}_L$.
		\item[]$(2)\Longrightarrow (1)$: Assume $(2)$. Let $h\in \ell^2(E)$. For all $l\in \mathbb{N}_L$, define $h_l\in \ell^2(E_l)$ as the restriction of $h$ en $E_l$, i.e $h_l=h|_{E_l}$. We have $\displaystyle{\sum_{j\in E}\vert h(j)\vert^2=\sum_{l\in \mathbb{N}_L}\sum_{j\in E_l} \vert h_l(j)\vert^2}$, then $\|h\|^2=\displaystyle{\sum_{l\in \mathbb{N}_L}\|h_l\|^2}.$ It is also clear that  $\langle h,e^{2\pi i \frac{m}{M}.}\chi_{E_l}\rangle=\langle h_l,e^{2\pi i \frac{m}{M}.}\chi_{E_l}\rangle$. Since For all $l\in \mathbb{N}_L$, $\{e^{2\pi i \frac{m}{M}.}\chi_{E_l}\}_{m\in \mathbb{N}_M}$ is a tight frame for $\ell^2(E_l)$ with frame bound $M$, then for all $l\in \mathbb{N}_l$, we have $M\|h_l\|^2=\displaystyle{\sum_{m\in \mathbb{N}_M}\vert \langle h_l,e^{2\pi i \frac{m}{M}.}\chi_{E_l}\rangle \vert^2}.$ Hence: 
		$$M\|h\|^2=\displaystyle{\sum_{l\in \mathbb{N}_L}\sum_{m\in \mathbb{N}_M}\vert \langle h,e^{2\pi i \frac{m}{M}.}\chi_{E_l}\rangle \vert^2}.$$
		This for all $h\in \ell^2(E_l)$. Hence $\{e^{2\pi i \frac{m}{M}.}\chi_{E_l}\}_{m\in \mathbb{N}_M, \, l\in \mathbb{N}_L}$ is a tight frame for $\ell^2(E)$ with frame bound $M$.
	\end{enumerate}

\label{lem4.4}
	Let $L,M\in \mathbb{N}$ and $E_0,\,E_1,\, \ldots,\,E_{L-1}\subset \mathbb{Z}$ be mutually disjoint. Denote $E=\displaystyle{\bigcup_{l\in \mathbb{N}_L}E_l}$. Then the following statements are equivalent:
	\begin{enumerate}
		\item $\{e^{2\pi i \frac{m}{M}.}\chi_{E_l}\}_{m\in \mathbb{N}_M, \, l\in \mathbb{N}_L}$ is a tight frame for $\ell^2(E)$ with frame bound $M$.
		\item $\{e^{2\pi i \frac{m}{M}.}\chi_{E_l}\}_{m\in \mathbb{N}_M, \, l\in \mathbb{N}_L}$ is complete in  $\ell^2(E)$.
		\item For all $l\in \mathbb{N}_L$, $E_l$ is $M\mathbb{Z}$-congruent to a subset of $\mathbb{N}_M$.
		\item For all $l\in \mathbb{N}_L$, $\displaystyle{\sum_{k\in \mathbb{Z}}\chi_{E_l}(.+kM)\leq 1}$ on $\mathbb{Z}$.
	\end{enumerate}

\label{prop4.5}
	Then the following statements are equivalent:
	\begin{enumerate}
		\item There exist $g:=\{g_l\}_{l\in \mathbb{N}_L}\subset \ell^2(\mathbb{S})$ such that $\mathcal{G}(g,L,M,N)$ is complete in $\ell^2(\mathbb{S})$.
		\item For all $j\in \mathbb{N}_{\frac{M}{q}}$, we have: 
		\begin{equation}
			card(\mathcal{K}_j)\leq qL.
		\end{equation} 
		\item $(10)$ holds for all $j\in \mathbb{Z}$.
	\end{enumerate}

\hspace{0.3cm}
	By remark \ref{rem1}, $card(\mathcal{K}_j)$ is $\displaystyle{\frac{M}{q}}$-periodic. Then $(2)\Longleftrightarrow (3)$.
	\begin{enumerate}
		\item[]$(1)\Longrightarrow (2)$: Assume $(1)$. Let $j\in \mathbb{N}_{\frac{M}{q}}$. Then by Theorem \ref{prop3.5}, $card(\mathcal{K}_j)=rank(Z_g(j,\theta)\,)\leq qL$ since $Z_g(j,\theta)\in \mathcal{M}_{qL,p}$.
		\item[]$(2)\Longrightarrow (1)$: Assume $(2)$. By Theorem \ref{prop3.5}, it suffices to find a matrix-valued function $Z:\mathbb{N}_{\frac{M}{q}}\times [0,1[\rightarrow \mathcal{M}_{qL,p}$ such that $Z(j,.)_{r,k}\in L^2([0,1[)$ for all $(j,r,k)\in \mathbb{N}_{\frac{M}{q}}\times \mathbb{N}_{qL}\times \mathbb{N}_p$ and for all $j\in \mathbb{N}_{\frac{M}{q}}$, if $k\notin \mathcal{K}_j$, the $k$-th column of $Z(j,.)$ is identically zero, and  such that $rank(Z(j,\theta)\,)=card(\mathcal{K}_j)$. Indeed, in this case, for all $l\in \mathbb{N}_L$, define $Z_l$ as the matrix-valued function $Z_l:\mathbb{N}_{\frac{M}{q}}\times [0,1[\rightarrow \mathcal{M}_{q,p}$ defined for all $j\in \mathbb{N}_{\frac{M}{q}}$, $\theta\in[0,1[$ by $Z_l(j,\theta):=Z(j,\theta)_{lq\leq r\leq (l+1)q-1,\, 0\leq k\leq p-1}$. Then by lemma \ref{lem2.2}, there exists a unique $g_l\in \ell^2(\mathbb{S})$ such that $Z_{g_l}=Z_l$. Denote $g=\{g_l\}_{l\in \mathbb{N}_L}$, then for all $j\in\mathbb{N}_{\frac{M}{q}}, \,\theta\in [0,1[$, $Z(j,\theta)=Z_g(j,\theta)$, hence by Theorem \ref{prop3.5}, $\mathcal{G}(g,L,M,N)$ is complete in $\ell^2(\mathbb{S})$ since $rank(Z_g(j,\theta)\,)=card(\mathcal{K}_j)$. \\
		For the existence of a such matrix-valued function: Let $j\in \mathbb{N}_{\frac{M}{q}}$ and a.e $\theta \in [0,1[$.  Define a $qL\times p$ constant matrix-valued function $Z(j,.):=(Z^0(j,.),Z^1(j,.),\ldots, Z^{p-1}(j,.)\,)$ on $[0,1[$, where $Z^k(j,.)$ is the $k$-th column of $Z(j,.)$ for $k\in \mathbb{N}_p$, such that $Z^k(j,.)=0$ if $k\notin \mathcal{K}_j$ and $\{Z^k(j,.),\; k\in \mathcal{K}_j\}$ is linearly independent in $\mathbb{C}^{qL}$. This is possible since $card(\mathcal{K}_j)\leq qL$. Then for a.e $\theta \in [0,1[$,  $rank(Z(j,\theta)\,)=card(\mathcal{K}_j)$. Hence we obtain the desired matrix-valued function $Z$.
	\end{enumerate}

\label{prop4.6}
